package io.github.diodeme.ji.agent.core;

import io.github.diodeme.ji.agent.AgentRuntime;
import io.github.diodeme.ji.agent.AgentRuntimeBuilder;
import io.github.diodeme.ji.agent.RuntimeConfiguration;

public final class CoreAgentRuntimeFactory implements AgentRuntimeBuilder.AgentRuntimeFactory {
    @Override
    public AgentRuntime create(RuntimeConfiguration configuration, boolean ownsExecutor) {
        return new CoreAgentRuntime(configuration, ownsExecutor);
    }
}
